          <div className="flex-1 flex flex-col">
            <AboutSection />
            <RulesSection />
            {/* LeaderboardSection hidden as requested */}
            <PrizesSection />
            <RegistrationFlow />
            <ContactSection />
            <Footer />
          </div>
        ) : (
          <div className="flex-1 flex flex-col">
            <MatchHistorySection />
            <Footer />
          </div>
