                    <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1">4. Email Address</label>
                      <input 
                        required 
                        type="email" 
                        value={formData.p2Email} 
                        onChange={e => handleChange('p2Email', e.target.value)}
