    if (log) {
      setEditingId(log.id);
      setFormData({
        p1Name: log.p1Name,
        p1Email: log.p1Email,
        p2Name: log.p2Name,
        p2Email: log.p2Email,
        winnerEmail: log.winnerEmail,
        loserEmail: log.loserEmail,
        score: log.score,
        proofFile: log.proofFile
      });
    } else {
      setEditingId(null);
      setFormData({
        p1Name: '',
        p1Email: '',
        p2Name: '',
        p2Email: '',
        winnerEmail: '',
        loserEmail: '',
        score: '',
        proofFile: null
      });
    }
    setIsModalOpen(true);
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Are you sure you want to delete this record?")) {
      setLogs(logs.filter(l => l.id !== id));
    }
