import React, { useState } from 'react';
import { Sidebar } from './components/Sidebar';
import { MobileNav } from './components/MobileNav';
import { TopHeader } from './components/TopHeader';
import { AboutSection } from './components/AboutSection';
import { RulesSection } from './components/RulesSection';
import { PrizesSection } from './components/PrizesSection';
import { RegistrationFlow } from './components/RegistrationFlow';
import { ContactSection } from './components/ContactSection';
import { MatchHistorySection } from './components/MatchHistorySection';
import { LeaderboardSection } from './components/LeaderboardSection';
import { ScoreRegistrationSection } from './components/ScoreRegistrationSection';
import { TestEmptyStateSection } from './components/TestEmptyStateSection';
import { Footer } from './components/Footer';

export default function App() {
  const [activeView, setActiveView] = useState<'home' | 'history' | 'leaderboard' | 'registration' | 'test'>('home');
  const [selectedPlayer, setSelectedPlayer] = useState<string | null>(null);

  const handleNavigate = (view: 'home' | 'history' | 'leaderboard' | 'registration' | 'test') => {
    setActiveView(view);
    // If navigating to history explicitly via menu, clear selected player (show own history)
    // If navigating to other pages, clear it as well.
    // The only time we keep it is if we are navigating FROM leaderboard TO history via click
    if (view !== 'history') {
      setSelectedPlayer(null);
    } else {
      // Navigating to history via menu button -> clear selected player to show "My History"
      // Note: If this function is called from Leaderboard click, we handle that separately below
      setSelectedPlayer(null);
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handlePlayerClick = (playerName: string) => {
    setSelectedPlayer(playerName);
    setActiveView('history');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <main className="min-h-screen bg-white flex flex-col lg:flex-row relative">
      <Sidebar activeView={activeView} onNavigate={handleNavigate} />
      <MobileNav activeView={activeView} onNavigate={handleNavigate} />

      <div className="flex-1 lg:ml-[300px] xl:ml-[340px] relative min-h-screen flex flex-col pt-32 lg:pt-0">
        <TopHeader onNavigate={handleNavigate} />

        {activeView === 'home' ? (
          <div className="flex-1 flex flex-col">
            <AboutSection />
            <RulesSection />
            <PrizesSection />
            <RegistrationFlow />
            <ContactSection />
            <Footer />
          </div>
        ) : activeView === 'history' ? (
          <div className="flex-1 flex flex-col">
            <MatchHistorySection 
              filterPlayer={selectedPlayer} 
              onBack={() => {
                setActiveView('leaderboard');
                setSelectedPlayer(null);
              }}
            />
            <Footer />
          </div>
        ) : activeView === 'leaderboard' ? (
          <div className="flex-1 flex flex-col">
            <LeaderboardSection onPlayerClick={handlePlayerClick} />
            <Footer />
          </div>
        ) : activeView === 'registration' ? (
           <div className="flex-1 flex flex-col">
            <ScoreRegistrationSection />
            <Footer />
          </div>
        ) : (
          <div className="flex-1 flex flex-col">
            <TestEmptyStateSection />
            <Footer />
          </div>
        )}
      </div>

      {/* Background layer for mobile view aesthetics */}
      <div className="lg:hidden w-full h-screen fixed inset-0 z-[-1] bg-[#000080]" />
    </main>
  );
}

import React from 'react';
import { motion } from 'framer-motion';
import { Calendar, CheckCircle, MapPin, XCircle, ArrowLeft } from 'lucide-react';
import { MATCH_HISTORY_DATA } from '../constants';
import { MatchRecord, MatchPlayer } from '../types';
import { EmptyState } from './EmptyState';

const CURRENT_USER = "Arran Kenna";

interface MatchCardProps {
  match: MatchRecord;
  focusPlayer?: string;
}

const MatchCard: React.FC<MatchCardProps> = ({ match, focusPlayer }) => {
  const primaryPlayer = focusPlayer || CURRENT_USER;

  // Sort players: Focus Player first, then others
  const players = [match.player1, match.player2].sort((a, b) => {
    if (a.name === primaryPlayer) return -1;
    if (b.name === primaryPlayer) return 1;
    return 0;
  });

  const renderPlayer = (player: MatchPlayer, index: number) => {
    const isFocus = player.name === primaryPlayer;
    const isMe = player.name === CURRENT_USER;
    const isWinner = player.isWinner;

    return (
      <div key={index} className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className={`w-8 h-8 rounded-full flex items-center justify-center text-xs font-black text-white ${
            isFocus ? 'bg-[#4c8bf5]' : 'bg-slate-300'
          }`}>
            {player.name.charAt(0)}
          </div>
          <span className="font-bold text-sm text-[#000080]">
            {player.name} {isMe && <span className="text-[#4c8bf5] text-xs opacity-70">(You)</span>}
          </span>
          {isWinner && <CheckCircle size={16} className="text-green-500" />}
        </div>
        <div className="flex gap-2">
          {player.scores.map((s, i) => (
            <span key={i} className={`w-8 h-8 rounded-lg flex items-center justify-center font-bold text-sm ${
               isWinner || isFocus ? 'bg-slate-100 text-[#000080]' : 'bg-slate-50 text-slate-500'
            }`}>
              {s}
            </span>
          ))}
        </div>
      </div>
    );
  };

  return (
    <div className="bg-white rounded-3xl overflow-hidden border border-slate-100 shadow-sm hover:shadow-md transition-all">
      {/* Card Header */}
      <div className="bg-[#4c8bf5]/10 p-4 flex flex-col sm:flex-row sm:justify-between sm:items-center gap-2 border-b border-[#4c8bf5]/10">
        <div>
          <h3 className="font-black text-[#000080] text-sm">{match.leagueName}</h3>
          <p className="text-[#000080]/60 text-xs font-bold mt-1 flex items-center gap-1">
            <MapPin size={12} />
            {match.market}, {match.city}
          </p>
        </div>
        <div className="text-right">
          <p className="text-[#000080] text-xs font-bold">{match.season}</p>
        </div>
      </div>

      {/* Meta Info */}
      <div className="px-6 py-4 flex items-center justify-between border-b border-slate-50">
        <div className="flex items-center gap-2 text-slate-500 text-xs font-bold uppercase tracking-wider">
          <Calendar size={14} className="text-[#4c8bf5]" />
          {match.date} &bull; {match.time}
        </div>
        <div className={`px-3 py-1 rounded-full text-[10px] font-black uppercase tracking-widest ${
          match.status === 'Completed' ? 'bg-green-100 text-green-700' : 
          match.status === 'Walkover' ? 'bg-orange-100 text-orange-700' : 'bg-slate-100 text-slate-500'
        }`}>
          {match.status}
        </div>
      </div>

      {/* Players & Scores */}
      <div className="px-6 py-4 space-y-4">
        {players.map((player, index) => renderPlayer(player, index))}
      </div>
    </div>
  );
};

